exercises.starter_code:
#include <stdio.h>

int main(void) {
    // struct Point; pointer set y=20
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    struct Point { int x, y; };
    struct Point pt = {5, 10};
    struct Point *p = &pt;
    p->y = 20;
    printf("{%d %d}\n", p->x, p->y);
    return 0;
}

