exercises.starter_code:
#include <stdio.h>

int main(void) {
    // nested struct, print company
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    struct Person { const char *name; };
    struct Employee { struct Person person; const char *company; };
    struct Employee emp = {{ "Bob" }, "Acme" };
    puts(emp.company);
    return 0;
}

